pub fn check_p61970_552_header_ap_con_simple_shacl_full_model_model_dependent_on_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("FullModel").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::FullModel>() {
            Some(o) => o, None => continue,
        };
        for r in &obj.base.dependent_on {
            let ref_id = r.mrid.trim_start_matches('#');
            if ref_id.is_empty() { continue; }
            if let Some(ref_entry) = dataset.entries.get(ref_id) {
                let allowed: &[&str] = &["DifferenceModel", "FullModel"];
                if !allowed.contains(&ref_entry.element.type_name()) {
                    violations.push(Violation {
                        object_id:   mrid.clone(),
                        rule_id:     "fh:Model.DependentOn-valueType".to_string(),
                        class:       "FullModel".to_string(),
                        property:    "Model.DependentOn".to_string(),
                        message:     "One of the following occurs: 1) The value type is not IRI; 2) The value type is not the right class.".to_string(),
                        severity:    "sh:Violation".to_string(),
                        name:        "Model.DependentOn-valueType".to_string(),
                        description: "This constraint validates the value type of the association at the used direction.".to_string(),
                    });
                }
            }
        }
    }
    violations
}

